package com.rescuefarm.ui.order;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.navigation.Navigation;import com.google.firebase.auth.FirebaseAuth;import com.rescuefarm.R;import com.rescuefarm.domain.model.Order;import java.util.*;
public class SellerOrderListFragment extends Fragment{private LinearLayout container;private TextView empty;private OrderViewModel vm;private String sellerId="";@Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_seller_order_list,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){container=v.findViewById(R.id.sellerOrderContainer);empty=v.findViewById(R.id.sellerOrderEmpty);sellerId=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();vm=new ViewModelProvider(this,new OrderViewModelFactory(requireContext())).get(OrderViewModel.class);vm.observeSellerOrders(sellerId).observe(getViewLifecycleOwner(),this::render);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==OrderLifecycleState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});v.findViewById(R.id.refreshSellerOrdersButton).setOnClickListener(x->vm.refreshSellerOrders(sellerId));if(!sellerId.isEmpty())vm.refreshSellerOrders(sellerId);}private void render(List<Order> values){container.removeAllViews();empty.setVisibility(values==null||values.isEmpty()?View.VISIBLE:View.GONE);if(values==null)return;for(Order o:values){Button b=new Button(requireContext());b.setAllCaps(false);b.setText(getString(R.string.seller_order_row_format,o.getOrderCode(),o.getStatus().name(),o.getPaymentStatus().name()));b.setOnClickListener(x->{Bundle args=new Bundle();args.putString("orderId",o.getId());Navigation.findNavController(requireView()).navigate(R.id.action_sellerOrderListFragment_to_orderDetailFragment,args);});container.addView(b);}}}
